-- Venue slugs are globally unique (brief S3-10, T61): `/m/<slug>`, `v/<slug>.json` and the table QR
-- links are public and global, while the old constraint made a slug unique per tenant only. Slugs
-- are lower-case by construction (provisionVenue accepts only the isVenueSlug pattern), so a plain
-- index is enough. Generated by drizzle-kit. It fails if two tenants already share a slug: rename
-- one of the venues first.
CREATE UNIQUE INDEX "venues_slug_unique" ON "restro"."venues" USING btree ("slug");
